  ('sjsu-2026-27-course-cs-46a', 'sjsu-2026-27', 'CS', '46A', 'Introduction to Programming', 4, 4, 'Introduction to programming for anyone new to the field or needing a refresher in basic Java programming syntax, object-oriented programming, control structures, and iteration, with hands-on compiling, execution, and debugging.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Introduction_to_Programming_CS_46A_Fall_2026_Tshukudu.pdf'),
  ('sjsu-2026-27-course-cs-46b', 'sjsu-2026-27', 'CS', '46B', 'Introduction to Data Structures', 4, 4, 'Fundamental data structures including lists, stacks, queues, and trees; efficient insertion, deletion, searching, and sorting; Big-O analysis, exceptions, hashing, Java collections, generics, iterators, interfaces, recursion, and debugging.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS46B_Introduction_to_Data_Structures_Fall_2026_section_1_Luo.pdf'),
  ('sjsu-2026-27-course-cs-47', 'sjsu-2026-27', 'CS', '47', 'Introduction to Computer Systems', 3, 3, 'Instruction sets, assembly language and assemblers, linkers and loaders, data representation and manipulation, interrupts, pointers, function calls, argument passing, and basic gate-level digital logic design.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Introduction_to_Computer_Systems_CS_47_Fall_2026_Paravastu.pdf'),
  ('sjsu-2026-27-course-cs-49c', 'sjsu-2026-27', 'CS', '49C', 'Programming in C', 3, 3, NULL, 'https://catalog.sjsu.edu/search_advanced.php?cur_cat_oid=23&search_database=Search&filter%5Bkeyword%5D=CS+49C'),
  ('sjsu-2026-27-course-cs-49j', 'sjsu-2026-27', 'CS', '49J', 'Programming in Java', 3, 3, NULL, 'https://catalog.sjsu.edu/search_advanced.php?cur_cat_oid=23&search_database=Search&filter%5Bkeyword%5D=CS+49J'),
  ('sjsu-2026-27-course-cs-100w', 'sjsu-2026-27', 'CS', '100W', 'Technical Writing Workshop', 3, 3, 'Advanced writing through technical reports and presentations, including subject-related reports, project proposals, and resumes. Satisfies Writing in the Disciplines.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS_100W_Sec01-Fall_2026-Cheilek.pdf'),
  ('sjsu-2026-27-course-cs-146', 'sjsu-2026-27', 'CS', '146', 'Data Structures and Algorithms', 3, 3, 'Advanced trees, priority queues, heaps, directed and undirected graphs, advanced searching and sorting, and divide-and-conquer, greedy, and dynamic programming algorithm design.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Syllabus%20CS%20146-01%20Fall%202026%20Navrati%20Saxena.pdf'),
  ('sjsu-2026-27-course-cs-147', 'sjsu-2026-27', 'CS', '147', 'Computer Architecture', 3, 3, 'Basic concepts of computer hardware structure and design, including processors, arithmetic logic units, pipelining, and memory hierarchy.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS147_Computer-Arch-Syllabus-Rao.pdf'),
  ('sjsu-2026-27-course-cs-149', 'sjsu-2026-27', 'CS', '149', 'Operating Systems', 3, 3, 'Memory management, processor scheduling and interrupts, concurrency, mutual exclusion, synchronization, deadlock, parallel computing, files, and a substantial programming project.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Operating_Systems_CS_149_Fall_2026_Andreopoulos.pdf'),
  ('sjsu-2026-27-course-cs-151', 'sjsu-2026-27', 'CS', '151', 'Object-Oriented Design', 3, 3, 'Design of classes and interfaces, object-oriented methodologies and notations, design patterns, generics, reflection, exception handling, concurrency, graphical interfaces, and software engineering tools.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Object_Oriented_Design_CS_151_Fall_2026_Kim.pdf'),
  ('sjsu-2026-27-course-cs-152', 'sjsu-2026-27', 'CS', '152', 'Programming Paradigms', 3, 3, 'Programming language syntax and semantics, data types and type checking, scope and bindings, functional and logic programming, and extensive coverage of a functional language.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Austin_CS_152_Fall_2026.pdf'),
  ('sjsu-2026-27-course-cs-154', 'sjsu-2026-27', 'CS', '154', 'Formal Languages and Computability', 3, 3, 'Finite automata, context-free languages, Turing machines, and computability.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Formal_Languages_and_Computability_CS_154_Fall_2026_Chen.pdf'),
  ('sjsu-2026-27-course-cs-157a', 'sjsu-2026-27', 'CS', '157A', 'Introduction to Database Management Systems', 3, 3, 'Database systems, entity-relationship models, relational model and algebra, SQL, transactions, security, interfaces, and an application programming project.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS157A-01%20Fall%202026-%20Syllabus_Wu.pdf'),
  ('sjsu-2026-27-course-cs-160', 'sjsu-2026-27', 'CS', '160', 'Software Engineering', 3, 3, 'Software engineering principles, requirements, design, configuration management, quality control, project planning, professional issues, and team-based development.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Fall2026_CS160_Sec3_Butt.pdf'),
  ('sjsu-2026-27-course-cs-166', 'sjsu-2026-27', 'CS', '166', 'Information Security', 3, 3, 'Cryptography, protocols, passwords, access control, software security, network security, and selected advanced security topics.', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/2026%20Fall%20-%20CS166%20-%20Section%201%20-Fabio%20Di%20Troia.pdf'),
