  ('sjsu-2026-27-course-cs-46aw', 'sjsu-2026-27', 'CS', '46AW', 'Introduction to Programming Workshop', NULL, NULL, NULL, 'https://catalog.sjsu.edu/search_advanced.php?cur_cat_oid=23&search_database=Search&filter%5Bkeyword%5D=CS+46AW'),
  ('sjsu-2026-27-course-cmpe-102', 'sjsu-2026-27', 'CMPE', '102', 'Assembly Language Programming', NULL, NULL, NULL, 'https://catalog.sjsu.edu/search_advanced.php?cur_cat_oid=23&search_database=Search&filter%5Bkeyword%5D=CMPE+102'),
