INSERT INTO requirement_groups (requirement_group_id, program_id, catalog_id, requirement_scope, parent_group_id, name, selection_rule, minimum_units, minimum_courses, notes, source_url) VALUES
  ('sjsu-cs-2026-major', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', NULL, 'Computer Science BS major requirements', 'Complete all required groups and 14 units of approved major electives.', NULL, NULL, 'A grade of C- or better is required in courses used for the major. Exact catalog page was blocked; confirmed components are reconciled from official SJSU articulation, program-review, FAQ, and Fall 2026 course sources.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-prep', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-major', 'Preparation and support for the major', 'Complete required mathematics, PHIL 134, one additional mathematics course, and the science unit rule.', NULL, NULL, NULL, 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-math-core', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-prep', 'Required mathematics', 'Complete MATH 30, MATH 31, MATH 42, and MATH 39.', 13, 4, NULL, 'https://info.sjsu.edu/web-dbgen/artic/AMRIVER/template-22.html'),
  ('sjsu-cs-2026-math-choice', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-prep', 'Additional mathematics course', 'Choose one: MATH 32, MATH 142, or MATH 161A.', 3, 1, 'Choice structure is supported by longstanding official BSCS materials but could not be read directly from the blocked 2026-27 program page; retained as ambiguous.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-ethics', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-prep', 'Computing ethics', 'Complete PHIL 134.', 3, 1, 'Also satisfies current GE UD Area 3.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-science', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-prep', 'BSCS science requirement', 'Complete 8 lower-division science units; at least 6 units must come from the listed approved science courses. Remaining units may be satisfied by GE Areas 5A, 5B, and 5C.', 8, NULL, NULL, 'https://info.sjsu.edu/web-dbgen/artic/AMRIVER/template-22.html'),
  ('sjsu-cs-2026-lower-core', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-major', 'Lower-division computer science core', 'Complete CS 46A, CS 46B, and CS 47.', 11, 3, NULL, 'https://info.sjsu.edu/web-dbgen/artic/AMRIVER/template-22.html'),
  ('sjsu-cs-2026-lower-elective', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-major', 'Lower-division major elective', 'Complete one of CS 49C or CS 49J.', 3, 1, NULL, 'https://info.sjsu.edu/web-dbgen/artic/AMRIVER/template-22.html'),
  ('sjsu-cs-2026-upper-core', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-major', 'Upper-division computer science core and WID', 'Complete CS 100W, CS 146, CS 147, CS 149, CS 151, CS 152, CS 154, CS 157A, CS 160, and CS 166.', 30, 10, 'CS 100W must be passed with C or better; the other major courses require C- or better.', 'https://www.sjsu.edu/cs/docs/action-plan/CS_Self-Study_2022.pdf'),
  ('sjsu-cs-2026-electives', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-major', 'Major electives', 'Complete 14 units subject to the catalog distributional constraint and upper-division MATH/CS unit constraint.', 14, NULL, 'The current catalog''s exact allocation among the option pools could not be retrieved because the catalog host returned 403. Options are preserved, but the distribution rule is unresolved.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-primary-electives', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-electives', 'Approved upper-division CS electives', 'Select eligible courses as permitted by the unresolved 14-unit distribution rule.', NULL, NULL, 'Option membership located from the current program structure; direct catalog verification blocked.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-additional-ud', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-electives', 'Additional upper-division CS electives', 'Select eligible courses as permitted by the unresolved 14-unit distribution rule.', NULL, NULL, 'Option membership located from the current program structure; direct catalog verification blocked.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-cs-2026-other-electives', 'sjsu-cs-bs-2026-27', 'sjsu-2026-27', 'major', 'sjsu-cs-2026-electives', 'Other approved CS and mathematics electives', 'Courses may count only as permitted by the current catalog distributional rule and any department-approval limits.', NULL, NULL, 'Only one BSCS elective may normally be satisfied by a CS 85/185 topics course; exact 2026-27 distribution remains unresolved.', 'https://catalog.sjsu.edu/preview_program.php?catoid=23&poid=18783&returnto=8470'),
  ('sjsu-ge-2026', NULL, 'sjsu-2026-27', 'university_ge', NULL, 'SJSU General Education', 'Complete 43 units: 34 lower-division and 9 upper-division GE.', 43, NULL, 'Applies to students beginning college in Fall 2025 or later; catalog rights may differ.', 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-lower', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026', 'Lower-division Core GE', 'Complete all Areas 1 through 6.', 34, NULL, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-1a', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 1A Written Communication I', 'Complete one 3-unit course with C- or better.', 3, 1, 'Reflection on College Writing Self-Placement is the published placement prerequisite.', 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-1b', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 1B Critical Thinking and Writing', 'Complete one 3-unit course with C- or better.', 3, 1, 'Area 1A with C- or better is prerequisite.', 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-1c', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 1C Oral Communication', 'Complete one 3-unit course with C- or better.', 3, 1, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-2', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 2 Mathematical Concepts and Quantitative Reasoning', 'Complete one 3-unit course with C- or better.', 3, 1, 'MATH 30 required by BSCS satisfies this area.', 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-3', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 3 Arts and Humanities', 'Complete one 3-unit Arts course and one 3-unit Humanities course.', 6, 2, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-4', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 4 Social and Behavioral Sciences', 'Complete two 3-unit courses.', 6, 2, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-5', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 5 Physical and Biological Sciences', 'Complete Physical Science (3), Biological Science (3), and Science Laboratory (1); the lab may be embedded in 5A or 5B.', 7, NULL, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-6', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-lower', 'Area 6 Ethnic Studies', 'Complete one 3-unit course with C- or better.', 3, 1, NULL, 'https://www2.sjsu.edu/general-education/docs/GE%20Guidelines_Updated_May2026.pdf'),
  ('sjsu-ge-2026-upper', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026', 'Upper-division SJSU Studies', 'Complete one course in each of UD Areas 2/5, 3, and 4.', 9, 3, 'Upper-division standing required. Official sources conflict on whether all Core GE or only lower-division Areas 1 and 2 must first be complete; conservative rule retained in notes/evidence.', 'https://www.sjsu.edu/general-education/ge-requirements/upper-division.php'),
  ('sjsu-ge-2026-ud25', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-upper', 'UD Area 2/5 Earth, Environment, and Sustainability', 'Complete one 3-unit course.', 3, 1, NULL, 'https://www.sjsu.edu/general-education/ge-requirements/upper-division.php'),
  ('sjsu-ge-2026-ud3', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-upper', 'UD Area 3 Cultures and Global Understanding', 'Complete one 3-unit course.', 3, 1, 'PHIL 134 required by BSCS satisfies this area.', 'https://www.sjsu.edu/general-education/ge-requirements/upper-division.php'),
  ('sjsu-ge-2026-ud4', NULL, 'sjsu-2026-27', 'university_ge', 'sjsu-ge-2026-upper', 'UD Area 4 Self, Society, and Equality in the U.S.', 'Complete one 3-unit course.', 3, 1, NULL, 'https://www.sjsu.edu/general-education/ge-requirements/upper-division.php')
