INSERT INTO prerequisite_rules (prerequisite_rule_id, course_id, rule_type, raw_text, normalized_expression, source_url) VALUES
  ('sjsu-2026-27-cs-46a-prereq', 'sjsu-2026-27-course-cs-46a', 'prerequisite', 'Math Enrollment Category M-I, M-II, or M-III, or MATH 1 with a grade of C- or better; and an allowed major; or instructor consent.', '(placement M-I OR M-II OR M-III OR MATH 1 >= C-) AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Introduction_to_Programming_CS_46A_Fall_2026_Tshukudu.pdf'),
  ('sjsu-2026-27-cs-46b-prereq', 'sjsu-2026-27-course-cs-46b', 'prerequisite', 'CS 46A or CS 46AX (with grade of C- or better). If CS 46A was not in Java, CS 46AW also required. Math Enrollment Category M-I or M-II and satisfactory score on the Precalculus Proficiency Assessment (70 or higher), or MATH 19 with C- or better, or MATH 18A and MATH 18B with C- or better; allowed majors only.', '(CS 46A >= C- OR CS 46AX >= C-) AND (if not Java then CS 46AW) AND ((M-I OR M-II) AND PPA>=70 OR MATH 19>=C- OR (MATH 18A>=C- AND MATH 18B>=C-)) AND allowed_major', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS46B_Introduction_to_Data_Structures_Fall_2026_section_1_Luo.pdf'),
  ('sjsu-2026-27-cs-47-prereq', 'sjsu-2026-27-course-cs-47', 'prerequisite', 'CS 42 or MATH 42, and CS 46B (with a grade of C- or better); allowed majors only.', '(CS 42 OR MATH 42) AND CS 46B>=C- AND allowed_major', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Introduction_to_Computer_Systems_CS_47_Fall_2026_Paravastu.pdf'),
  ('sjsu-2026-27-cs-100w-prereq', 'sjsu-2026-27-course-cs-100w', 'prerequisite', 'Area 1B/A3 or equivalent second-semester composition course with C- or better; completion of Core GE; and upper-division standing; or graduate/postbaccalaureate level. Allowed declared majors only. Must be passed with C or better for GWAR.', '((Area 1B>=C- AND Core GE complete AND upper_division_standing) OR graduate_or_postbaccalaureate) AND allowed_major', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS_100W_Sec01-Fall_2026-Cheilek.pdf'),
  ('sjsu-2026-27-cs-146-prereq', 'sjsu-2026-27-course-cs-146', 'prerequisite', 'MATH 30, MATH 42, CS 46B, and [(CS 48 or CS 49J) if CS 46B was not in Java], each with C- or better; allowed majors only; or instructor consent.', 'MATH 30>=C- AND MATH 42>=C- AND CS 46B>=C- AND (if CS 46B not Java then (CS 48>=C- OR CS 49J>=C-)) AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Syllabus%20CS%20146-01%20Fall%202026%20Navrati%20Saxena.pdf'),
  ('sjsu-2026-27-cs-147-prereq', 'sjsu-2026-27-course-cs-147', 'prerequisite', 'CS 47 or CMPE 102 or equivalent, with a grade of C- or better.', '(CS 47 OR CMPE 102 OR equivalent)>=C-', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS147_Computer-Arch-Syllabus-Rao.pdf'),
  ('sjsu-2026-27-cs-149-prereq', 'sjsu-2026-27-course-cs-149', 'prerequisite', 'CS 47 or CMPE 102 with C- or better, and CS 146 with C- or better; allowed majors only; or instructor consent.', '(CS 47>=C- OR CMPE 102>=C-) AND CS 146>=C- AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Operating_Systems_CS_149_Fall_2026_Andreopoulos.pdf'),
  ('sjsu-2026-27-cs-151-prereq', 'sjsu-2026-27-course-cs-151', 'prerequisite', 'MATH 42, CS 46B, and [(CS 48 or CS 49J) if CS 46B was not in Java], each with C- or better; allowed majors only; or instructor consent.', 'MATH 42>=C- AND CS 46B>=C- AND (if CS 46B not Java then (CS 48>=C- OR CS 49J>=C-)) AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Object_Oriented_Design_CS_151_Fall_2026_Kim.pdf'),
  ('sjsu-2026-27-cs-152-prereq', 'sjsu-2026-27-course-cs-152', 'prerequisite', 'CS 151 or CMPE 135 with a grade of C- or better; allowed majors only; or instructor consent.', '(CS 151>=C- OR CMPE 135>=C-) AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Austin_CS_152_Fall_2026.pdf'),
  ('sjsu-2026-27-cs-154-prereq', 'sjsu-2026-27-course-cs-154', 'prerequisite', 'MATH 42 or MATH 42X and CS 46B, with a grade of C- or better in each; allowed majors only; or instructor consent.', '(MATH 42>=C- OR MATH 42X>=C-) AND CS 46B>=C- AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Formal_Languages_and_Computability_CS_154_Fall_2026_Chen.pdf'),
  ('sjsu-2026-27-cs-157a-prereq', 'sjsu-2026-27-course-cs-157a', 'prerequisite', 'CS 146 with a grade of C- or better; allowed majors only; or instructor consent.', 'CS 146>=C- AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/CS157A-01%20Fall%202026-%20Syllabus_Wu.pdf'),
  ('sjsu-2026-27-cs-160-prereq', 'sjsu-2026-27-course-cs-160', 'prerequisite', 'CS 146 and CS 151 with C- or better in each; CS 100W with C or better.', 'CS 146>=C- AND CS 151>=C- AND CS 100W>=C', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/Fall2026_CS160_Sec3_Butt.pdf'),
  ('sjsu-2026-27-cs-166-prereq', 'sjsu-2026-27-course-cs-166', 'prerequisite', 'CS 146 with C- or better and either CS 47, CMPE 102, or CMPE 120 with C- or better; allowed majors only; or instructor consent.', 'CS 146>=C- AND (CS 47>=C- OR CMPE 102>=C- OR CMPE 120>=C-) AND (allowed_major OR instructor_consent)', 'https://www.sjsu.edu/cs/docs/syllabi/fall26/2026%20Fall%20-%20CS166%20-%20Section%201%20-Fabio%20Di%20Troia.pdf')
