-- SJSU Computer Science BS, 2026-2027 catalog-rights dataset
-- Generated 2026-09-25. PostgreSQL-compatible and idempotent.
-- Coverage limitations and conflicts are preserved in source_evidence; no degree-audit guarantee.

BEGIN;

CREATE TABLE IF NOT EXISTS universities (
  university_id TEXT PRIMARY KEY, canonical_name TEXT NOT NULL, campus_name TEXT, official_domain TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS catalog_editions (
  catalog_id TEXT PRIMARY KEY, university_id TEXT NOT NULL REFERENCES universities,
  academic_year TEXT NOT NULL, effective_start DATE, effective_end DATE,
  catalog_url TEXT NOT NULL, retrieved_at TIMESTAMP NOT NULL,
  UNIQUE (university_id, academic_year)
);
CREATE TABLE IF NOT EXISTS programs (
  program_id TEXT PRIMARY KEY, catalog_id TEXT NOT NULL REFERENCES catalog_editions,
  major_name TEXT NOT NULL, degree_type TEXT, college_or_school TEXT, program_url TEXT NOT NULL,
  UNIQUE (catalog_id, major_name, degree_type)
);
CREATE TABLE IF NOT EXISTS courses (
  course_id TEXT PRIMARY KEY, catalog_id TEXT NOT NULL REFERENCES catalog_editions,
  subject_code TEXT NOT NULL, course_number TEXT NOT NULL, title TEXT NOT NULL,
  units_min NUMERIC, units_max NUMERIC, description TEXT, course_url TEXT NOT NULL,
  UNIQUE (catalog_id, subject_code, course_number)
);
CREATE TABLE IF NOT EXISTS requirement_groups (
  requirement_group_id TEXT PRIMARY KEY, program_id TEXT REFERENCES programs,
  catalog_id TEXT NOT NULL REFERENCES catalog_editions,
  requirement_scope TEXT NOT NULL CHECK (requirement_scope IN ('major','university_ge')),
  parent_group_id TEXT REFERENCES requirement_groups, name TEXT NOT NULL,
  selection_rule TEXT NOT NULL, minimum_units NUMERIC, minimum_courses INTEGER,
  notes TEXT, source_url TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS requirement_courses (
  requirement_group_id TEXT NOT NULL REFERENCES requirement_groups,
  course_id TEXT NOT NULL REFERENCES courses, is_required BOOLEAN NOT NULL,
  list_label TEXT, PRIMARY KEY (requirement_group_id, course_id)
);
CREATE TABLE IF NOT EXISTS prerequisite_rules (
  prerequisite_rule_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses,
  rule_type TEXT NOT NULL CHECK (rule_type IN ('prerequisite','corequisite','recommended','restriction','consent','placement','other')),
  raw_text TEXT NOT NULL, normalized_expression TEXT, source_url TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS prerequisite_rule_courses (
  prerequisite_rule_id TEXT NOT NULL REFERENCES prerequisite_rules,
  required_course_id TEXT NOT NULL REFERENCES courses,
  relationship TEXT NOT NULL CHECK (relationship IN ('all_of','any_of','one_of','minimum_grade','concurrent','other')),
  minimum_grade TEXT, PRIMARY KEY (prerequisite_rule_id, required_course_id)
);
CREATE TABLE IF NOT EXISTS source_evidence (
  evidence_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL,
  source_url TEXT NOT NULL, page_title TEXT, quoted_text TEXT,
  retrieved_at TIMESTAMP NOT NULL,
  confidence TEXT NOT NULL CHECK (confidence IN ('confirmed','ambiguous','unresolved')),
  notes TEXT
);

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

COMMIT;
